CREATE TYPE public.group_practice_type AS ENUM ('solo','partnership','association','incorporated');
CREATE TYPE public.group_member_role AS ENUM ('principal','partner','associate');
ALTER TABLE public.practices ADD COLUMN name text GENERATED ALWAYS AS (practice_name) STORED, ADD COLUMN bhf_practice_number text GENERATED ALWAYS AS (bhf_number) STORED, ADD COLUMN physical_address text GENERATED ALWAYS AS (address) STORED, ADD COLUMN practice_type public.group_practice_type NOT NULL DEFAULT 'solo', ADD COLUMN vat_number text, ADD COLUMN city text, ADD COLUMN province text, ADD COLUMN logo_url text, ADD COLUMN is_medical_aid_practice boolean NOT NULL DEFAULT false;
ALTER TABLE public.doctors ADD COLUMN hpcsa_number text GENERATED ALWAYS AS (license_number) STORED, ADD COLUMN individual_bhf_number text GENERATED ALWAYS AS (bhf_number) STORED, ADD COLUMN physical_practice_address text;
UPDATE public.doctors SET physical_practice_address = NULLIF(trim(practice_address),'') WHERE practice_address IS NOT NULL;
ALTER TABLE public.practice_members ADD COLUMN doctor_id uuid REFERENCES public.doctors(id) ON DELETE CASCADE, ADD COLUMN member_role public.group_member_role NOT NULL DEFAULT 'associate', ADD COLUMN individual_bhf_number text, ADD COLUMN joined_at timestamptz NOT NULL DEFAULT now(), ADD COLUMN is_active boolean GENERATED ALWAYS AS (status = 'active'::public.practice_member_status) STORED;
UPDATE public.practice_members m SET doctor_id=d.id, individual_bhf_number=d.bhf_number, member_role=CASE WHEN m.role='owner' THEN 'principal'::public.group_member_role ELSE 'associate'::public.group_member_role END FROM public.doctors d WHERE m.user_id=d.profile_id AND m.role IN ('owner','doctor');
ALTER TABLE public.practice_members ADD CONSTRAINT practice_members_practice_doctor_unique UNIQUE (practice_id,doctor_id);
CREATE TABLE public.practice_admins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), practice_id uuid NOT NULL REFERENCES public.practices(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(practice_id,user_id));
GRANT SELECT,INSERT,UPDATE ON public.practice_admins TO authenticated;
GRANT ALL ON public.practice_admins TO service_role;
ALTER TABLE public.practice_admins ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_practice_admin(_user_id uuid,_practice_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'practice_admin') AND EXISTS(SELECT 1 FROM public.practice_admins WHERE user_id=_user_id AND practice_id=_practice_id) $$;
REVOKE ALL ON FUNCTION public.is_practice_admin(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_practice_admin(uuid,uuid) TO authenticated,service_role;
CREATE POLICY practice_admins_read ON public.practice_admins FOR SELECT TO authenticated USING(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),practice_id));
CREATE POLICY practice_admins_insert ON public.practice_admins FOR INSERT TO authenticated WITH CHECK(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),practice_id));
CREATE POLICY practice_admins_update ON public.practice_admins FOR UPDATE TO authenticated USING(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),practice_id)) WITH CHECK(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),practice_id));
CREATE TRIGGER practice_admins_updated BEFORE UPDATE ON public.practice_admins FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE FUNCTION public.grant_practice_admin_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.user_id,'practice_admin') ON CONFLICT(user_id,role) DO NOTHING; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.grant_practice_admin_role() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER grant_practice_admin_role AFTER INSERT OR UPDATE OF user_id ON public.practice_admins FOR EACH ROW EXECUTE FUNCTION public.grant_practice_admin_role();
CREATE POLICY foundation_practices_read ON public.practices FOR SELECT TO authenticated USING(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),id));
CREATE POLICY foundation_practices_insert ON public.practices FOR INSERT TO authenticated WITH CHECK(public.is_platform_admin(auth.uid()));
CREATE POLICY foundation_practices_update ON public.practices FOR UPDATE TO authenticated USING(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),id)) WITH CHECK(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),id));
CREATE POLICY foundation_members_read ON public.practice_members FOR SELECT TO authenticated USING(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),practice_id));
CREATE POLICY foundation_members_insert ON public.practice_members FOR INSERT TO authenticated WITH CHECK(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),practice_id));
CREATE POLICY foundation_members_update ON public.practice_members FOR UPDATE TO authenticated USING(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),practice_id)) WITH CHECK(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),practice_id));
CREATE FUNCTION public.group_practice_directory() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; RETURN jsonb_build_object('practices',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',practice_name,'bhf_practice_number',bhf_number,'practice_type',practice_type,'city',city,'province',province,'logo_url',logo_url)),'[]') FROM public.practices WHERE is_active),'members',(SELECT coalesce(jsonb_agg(jsonb_build_object('practice_id',m.practice_id,'doctor_id',m.doctor_id,'member_role',m.member_role,'hpcsa_number',d.license_number,'individual_bhf_number',d.bhf_number)),'[]') FROM public.practice_members m JOIN public.practices p ON p.id=m.practice_id JOIN public.doctors d ON d.id=m.doctor_id WHERE m.is_active AND p.is_active)); END $$;
CREATE FUNCTION public.group_practice_members(_practice_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),_practice_id)) THEN RAISE EXCEPTION 'Practice access denied'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',m.id,'doctor_id',d.id,'full_name',p.full_name,'email',m.email,'member_role',m.member_role,'is_active',m.is_active,'hpcsa_number',d.license_number,'individual_bhf_number',d.bhf_number,'physical_practice_address',d.physical_practice_address)),'[]') FROM public.practice_members m JOIN public.doctors d ON d.id=m.doctor_id JOIN public.profiles p ON p.id=d.profile_id WHERE m.practice_id=_practice_id); END $$;
CREATE FUNCTION public.add_group_practice_doctor(_practice_id uuid,_email text,_member_role public.group_member_role) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.doctors%ROWTYPE; p public.profiles%ROWTYPE; result uuid; BEGIN IF NOT(public.is_platform_admin(auth.uid()) OR public.is_practice_admin(auth.uid(),_practice_id)) THEN RAISE EXCEPTION 'Practice access denied'; END IF; SELECT * INTO p FROM public.profiles WHERE lower(email)=lower(trim(_email)); IF NOT FOUND THEN RAISE EXCEPTION 'No existing doctor found for that email'; END IF; SELECT * INTO d FROM public.doctors WHERE profile_id=p.id; IF NOT FOUND THEN RAISE EXCEPTION 'No existing doctor found for that email'; END IF; INSERT INTO public.practice_members(practice_id,user_id,doctor_id,full_name,email,role,hpcsa_number,individual_bhf_number,status,member_role) VALUES(_practice_id,p.id,d.id,p.full_name,p.email,CASE WHEN nullif(trim(d.license_number),'') IS NULL THEN 'owner'::public.practice_role ELSE 'doctor'::public.practice_role END,d.license_number,d.bhf_number,'active',_member_role) ON CONFLICT(practice_id,email) DO UPDATE SET doctor_id=EXCLUDED.doctor_id, member_role=EXCLUDED.member_role,status='active' RETURNING id INTO result; RETURN result; END $$;
CREATE FUNCTION public.assign_group_practice_admin(_practice_id uuid,_email text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; BEGIN IF NOT public.is_platform_admin(auth.uid()) THEN RAISE EXCEPTION 'Admin access required'; END IF; SELECT id INTO uid FROM public.profiles WHERE lower(email)=lower(trim(_email)); IF uid IS NULL THEN RAISE EXCEPTION 'No account found for that email'; END IF; INSERT INTO public.practice_admins(practice_id,user_id) VALUES(_practice_id,uid) ON CONFLICT(practice_id,user_id) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.group_practice_directory(),public.group_practice_members(uuid),public.add_group_practice_doctor(uuid,text,public.group_member_role),public.assign_group_practice_admin(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.group_practice_directory(),public.group_practice_members(uuid),public.add_group_practice_doctor(uuid,text,public.group_member_role),public.assign_group_practice_admin(uuid,text) TO authenticated,service_role;